package com.madar.files;
import org.json.*;
import java.io.IOException;
import java.util.*;

/** Validate output types between a small sequence of existing file operations. */
final class AgentWorkflow {
 static final Set<String> FILE_TOOLS=new HashSet<>(Arrays.asList("convert","compress","resize","background","rotate","targetImage","removebg","adjust","flip","trim","mute","audio","music","sound","compressPdf","extract"));
 static JSONObject stepSchema()throws Exception{JSONObject atomic=AgentTools.schemaBase("");JSONArray names=new JSONArray();for(String kind:Arrays.asList("image","video","audio","pdf"))for(String t:AgentTools.tools(kind))if(FILE_TOOLS.contains(t)&&!names.toString().contains("\""+t+"\""))names.put(t);return new JSONObject().put("type","object").put("properties",new JSONObject().put("tool",new JSONObject().put("type","string").put("enum",names)).put("fields",atomic.getJSONObject("properties").getJSONObject("fields"))).put("required",new JSONArray(Arrays.asList("tool","fields"))).put("additionalProperties",false);}
 static String output(JSONObject step,String kind)throws Exception{String tool=step.getString("tool");if(!FILE_TOOLS.contains(tool))throw new IOException("هذه الأداة تحتاج شاشة تفاعلية؛ لا تُستخدم كخطوة وسيطة");Map<String,String> fields=new HashMap<>();JSONArray values=step.getJSONArray("fields");for(int i=0;i<values.length();i++){JSONObject f=values.getJSONObject(i);fields.put(f.getString("name"),f.getString("value"));}if(tool.equals("audio"))return "audio";if(tool.equals("music")&&fields.getOrDefault("musicOutput",kind.equals("video")?"video":"audio").equals("audio"))return "audio";String format=fields.getOrDefault("format",kind.equals("pdf")?"png":kind.equals("image")?"jpg":kind.equals("audio")?"m4a":"mp4");if(format!=null&&tool.equals("convert")){if(format.equals("pdf"))return "pdf";if(Arrays.asList("mp3","wav","m4a","flac","ogg").contains(format))return "audio";if(Arrays.asList("jpg","png","webp").contains(format))return "image";}return kind;}
 static void validate(JSONObject plan,String kind)throws Exception{JSONArray steps=plan.optJSONArray("steps");if(steps==null||steps.length()==0)return;if(steps.length()>4)throw new IOException("الحد خمس عمليات متتابعة في الطلب");String next=output(plan,kind);for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);for(Iterator<String> it=step.keys();it.hasNext();)if(!Arrays.asList("tool","fields").contains(it.next()))throw new IOException("خطوة غير صالحة");AgentTools.validate(new JSONObject(step.toString()).put("message",""),next);next=output(step,next);}}
}
